export default {
  props: {
    records: {
      type: Array,
      required: true
    }
  },
  data() {
    return {
      activeTab: 'all',
      searchQuery: ''
    };
  },
  computed: {
    filteredRecords() {
      let filtered = [...this.records];

      // 搜索过滤
      if (this.searchQuery) {
        const query = this.searchQuery.toLowerCase();
        filtered = filtered.filter(record => record.url.toLowerCase().includes(query) || record.account.toLowerCase().includes(query));
      }

      // 标签过滤
      if (this.activeTab === 'recent') {
        // 按时间戳排序，取最近5条
        filtered.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
        return filtered.slice(0, 5);
      }
      return filtered;
    }
  },
  methods: {
    handleEdit(record) {
      this.$emit('edit-record', record);
    },
    handleDelete(record) {
      const index = this.records.findIndex(r => r.id === record.id);
      if (index !== -1) {
        this.$emit('delete-record', index);
      }
    }
  }
};
